def sqrt(x, epsilon, max_iter):
    if abs(x) < epsilon:
        return x

    x_0 = x
    n = 0

    for i in range(max_iter):
        x_n = (x_0 + 2/x_0) / 2
        x_0 = x_n
        n += 1

        if abs(x_0 - x_n) < epsilon:
            return x_n

    return x_n

